(2,	4,	'_form',	'<label> Ваше имя (обязательно)\n    [text* your-name] </label>\n\n<label> Ваш e-mail (обязательно)\n    [email* your-email] </label>\n\n<label> Тема\n    [text your-subject] </label>\n\n<label> Сообщение\n    [textarea your-message x5] </label>\n\n[submit \"Отправить\"]'),
(3,	4,	'_mail',	'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:24:\"Service \"[your-subject]\"\";s:6:\"sender\";s:48:\"[your-name] <wordpress@host1665312.hostland.pro>\";s:9:\"recipient\";s:21:\"office@aliveliyev.com\";s:4:\"body\";s:201:\"От: [your-name] <[your-email]>\nТема: [your-subject]\n\nСообщение:\n[your-message]\n\n-- \nЭто сообщение отправлено с сайта Service (http://host1665312.hostland.pro)\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
