(10,	1,	'2018-03-29 03:38:06',	'2018-03-29 00:38:06',	'<p style=\"text-align: center;\">Адрес нашего центрального офиса в г. Голицыно:</p>\r\n\r\n<p style=\"text-align: center;\">г. Голицыно, ул. Петровское шоссе, д. 8</p>\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\" async src=\"https://api-maps.yandex.ru/services/constructor/1.0/js/?um=constructor%3Aa70a28d1519d12fa58ee5aa5001caa6217c7a5e14a006fb34b0a69dbadc582d5&amp;width=500&amp;height=350&amp;lang=ru_RU&amp;scroll=true\"></script>',	'Контакты',	'',	'publish',	'closed',	'closed',	'',	'%d0%ba%d0%be%d0%bd%d1%82%d0%b0%d0%ba%d1%82%d1%8b',	'',	'',	'2019-03-20 17:11:21',	'2019-03-20 14:11:21',	'',	2,	'http://remont-dolgoprudniy.ru/?page_id=10',	0,	'page',	'',	0),
