(36,	1,	'2018-03-30 16:41:27',	'2018-03-30 13:41:27',	'',	'Авторизованный  сервисный центр',	'',	'publish',	'closed',	'closed',	'',	'%d0%b0%d0%b2%d1%82%d0%be%d1%80%d0%b8%d0%b7%d0%be%d0%b2%d0%b0%d0%bd%d0%bd%d1%8b%d0%b9-%d1%81%d0%b5%d1%80%d0%b2%d0%b8%d1%81%d0%bd%d1%8b%d0%b9-%d1%86%d0%b5%d0%bd%d1%82%d1%80',	'',	'',	'2018-03-30 16:41:27',	'2018-03-30 13:41:27',	'',	0,	'http://remont-dolgoprudniy.ru/?post_type=slider&#038;p=36',	0,	'slider',	'',	0),
